extends StaticBody2D

signal opened
signal closed

@export var requires_key: bool = false
@export var is_open: bool = false

@onready var collision_shape: CollisionShape2D = $CollisionShape2D
@onready var interaction_area: Area2D = $InteractionArea

var current_player: CharacterBody2D = null
var _frame_count: int = 0
var _last_interact_frame: int = -1


func _ready() -> void:
	interaction_area.body_entered.connect(_on_interaction_body_entered)
	interaction_area.body_exited.connect(_on_interaction_body_exited)
	_update_appearance()


func _process(_delta: float) -> void:
	_frame_count += 1
	if Input.is_action_just_pressed("interact"):
		_try_interact()


func _unhandled_input(event: InputEvent) -> void:
	if event.is_action_pressed("interact"):
		_try_interact()


func _try_interact() -> void:
	if _last_interact_frame == _frame_count:
		return
	_last_interact_frame = _frame_count

	if is_open:
		return

	var p: CharacterBody2D = _get_interacting_player()
	if p != null:
		if requires_key:
			var player_keys: int = int(p.get("keys"))
			if player_keys > 0:
				p.set("keys", player_keys - 1)
				open()
		else:
			open()


func _get_interacting_player() -> CharacterBody2D:
	if current_player != null:
		return current_player
	for body in interaction_area.get_overlapping_bodies():
		if body.name == "Player" and body is CharacterBody2D:
			return body as CharacterBody2D
	var scene_player: Node = get_tree().current_scene.find_child("Player", true, false)
	if scene_player != null and scene_player is CharacterBody2D:
		var cb := scene_player as CharacterBody2D
		if global_position.distance_to(cb.global_position) < 60.0:
			return cb
	return null


func open() -> void:
	if is_open:
		return
	is_open = true
	collision_shape.set_deferred("disabled", true)
	_update_appearance()
	opened.emit()


func close() -> void:
	if not is_open:
		return
	is_open = false
	collision_shape.set_deferred("disabled", false)
	_update_appearance()
	closed.emit()


func _update_appearance() -> void:
	if is_open:
		modulate.a = 0.3
	else:
		modulate.a = 1.0


func _on_interaction_body_entered(body: Node2D) -> void:
	if body.name == "Player" and body is CharacterBody2D:
		current_player = body as CharacterBody2D


func _on_interaction_body_exited(body: Node2D) -> void:
	if body == current_player:
		current_player = null

extends Area2D

signal activated
signal deactivated

@export var is_active: bool = false

var is_player_nearby: bool = false
var _frame_count: int = 0
var _last_interact_frame: int = -1


func _ready() -> void:
	body_entered.connect(_on_body_entered)
	body_exited.connect(_on_body_exited)
	_update_visual()


func _process(_delta: float) -> void:
	_frame_count += 1
	if Input.is_action_just_pressed("interact"):
		_try_interact()


func _unhandled_input(event: InputEvent) -> void:
	if event.is_action_pressed("interact"):
		_try_interact()


func _try_interact() -> void:
	if _last_interact_frame == _frame_count:
		return
	_last_interact_frame = _frame_count

	if _is_player_near():
		toggle()


func _is_player_near() -> bool:
	if is_player_nearby:
		return true
	for body in get_overlapping_bodies():
		if body.name == "Player":
			return true
	var scene_player: Node = get_tree().current_scene.find_child("Player", true, false)
	if scene_player != null and scene_player is Node2D:
		var n2d := scene_player as Node2D
		if global_position.distance_to(n2d.global_position) < 40.0:
			return true
	return false


func toggle() -> void:
	is_active = not is_active
	_update_visual()
	if is_active:
		activated.emit()
	else:
		deactivated.emit()


func _update_visual() -> void:
	if is_active:
		modulate = Color(0.4, 1.0, 0.4)
	else:
		modulate = Color(1.0, 0.4, 0.4)


func _on_body_entered(body: Node2D) -> void:
	if body.name == "Player":
		is_player_nearby = true


func _on_body_exited(body: Node2D) -> void:
	if body.name == "Player":
		is_player_nearby = false

extends CharacterBody2D

@export var max_speed: float = 200.0
@export var acceleration: float = 1200.0
@export var friction: float = 1000.0
@export var sprint_multiplier: float = 1.5
@export var bullet_scene: PackedScene = preload("res://bullet.tscn")
@export var shoot_cooldown: float = 0.25

var coins: int = 0
var hearts: int = 0
var keys: int = 0

var _time_since_last_shot: float = 1.0


func _physics_process(delta: float) -> void:
	_time_since_last_shot += delta

	var input_direction: Vector2 = get_input_direction()
	update_velocity(input_direction, delta)
	move_and_slide()

	if Input.is_action_pressed("shoot") and _time_since_last_shot >= shoot_cooldown:
		shoot()


func get_input_direction() -> Vector2:
	return Input.get_vector("move_left", "move_right", "move_up", "move_down")


func update_velocity(direction: Vector2, delta: float) -> void:
	if direction != Vector2.ZERO:
		var current_max_speed: float = max_speed
		if Input.is_action_pressed("sprint"):
			current_max_speed *= sprint_multiplier
		var target_velocity: Vector2 = direction * current_max_speed
		velocity = velocity.move_toward(target_velocity, acceleration * delta)
	else:
		velocity = velocity.move_toward(Vector2.ZERO, friction * delta)


func shoot() -> void:
	_time_since_last_shot = 0.0

	var mouse_position: Vector2 = get_global_mouse_position()
	var shoot_direction: Vector2 = global_position.direction_to(mouse_position)

	if shoot_direction == Vector2.ZERO:
		shoot_direction = Vector2.RIGHT

	var bullet_instance: Node2D = bullet_scene.instantiate() as Node2D
	bullet_instance.global_position = global_position
	bullet_instance.rotation = shoot_direction.angle()

	if "direction" in bullet_instance:
		bullet_instance.set("direction", shoot_direction)

	get_tree().current_scene.add_child(bullet_instance)


func collect(type: String, value: int) -> void:
	if type == "coin":
		coins += value
	elif type == "heart":
		hearts += value
	elif type == "key":
		keys += value

extends Area2D

@export var speed: float = 400.0

var direction: Vector2 = Vector2.RIGHT

@onready var lifetime_timer: Timer = $LifetimeTimer


func _ready() -> void:
	body_entered.connect(_on_body_entered)
	lifetime_timer.timeout.connect(_on_lifetime_timer_timeout)
	lifetime_timer.start()


func _physics_process(delta: float) -> void:
	global_position += direction * speed * delta


func _on_body_entered(_body: Node2D) -> void:
	queue_free()


func _on_lifetime_timer_timeout() -> void:
	queue_free()

