	var linked_health = get_prop(hurtbox, "health_component")
	check("hurtbox_linked", linked_health == health, "Il nodo Hurtbox deve avere la proprietà health_component collegata al nodo Health")

	call_if_exists(health, "take_damage", [1])
	await wait_frames(2)
	check("color_changed", crate.modulate != Color.WHITE, "Dopo il primo colpo la cassa deve modulare il colore")

	call_if_exists(health, "take_damage", [1])
	await wait_frames(2)
	var destroyed := not is_instance_valid(crate) or crate.is_queued_for_deletion()
	check("crate_destroyed", destroyed, "A zero punti vita la cassa deve chiamare queue_free()")

